proc sql;
create table thesis.exhibit10_gaap as
select a.*, b.*
from thesis.exhibit10_gaap as a, thesis.cik_gvkey_linking_table as b
where a.cik=b.cik and b.DATADATE1<=a.fdate<=DATADATE2;
quit;
data thesis.exhibit10_gaap;
set thesis.exhibit10_gaap;
if FLAG^=3 then delete;/*keep Flag = 3 where the GVKEY-CIK Link is valid*/
run;
proc sql;
create table thesis.exhibit10_gaap as
select a.*, b.sic
from thesis.exhibit10_gaap as a left join thesis.fyear_sic as b
on a.gvkey=b.gvkey and a.filingyear=b.fyear;
quit;
data thesis.exhibit10_gaap;
set thesis.exhibit10_gaap;
if 6000<=sic<=6999 then delete;
run;

/* Merge exhibit10_gaap with DealScan facilities with maturity of more than five yeats based on borrowers' identifier and effective date*/
/* Manually check whether the contract's lenders, loan type, loan amount, and maturity in my sample are the same as those in DealScan */
data thesis.dealscan_facility;
set thesis.dealscan_facility;
if maturity<60 then delete;
run;
data thesis.dealscan_compustat_linking;
set thesis.dealscan_compustat_linking_table;
if fic^='USA' then delete;
run;
proc sql;
create table thesis.dealscan_facility as
select a.*, b.*
from thesis.dealscan_facility as a, thesis.dealscan_compustat_linking as b
where a.facilityid=b.facid;
quit;
proc sql;
create table thesis.exhibit10_gaap as
select a.*, b.*
from thesis.exhibit10_gaap as a, thesis.dealscan_facility as b
where a.gvkey=b.gvkey and a.effectivedate-b.facilitystartdate<15 and a.effectivedate-b.facilitystartdate>-15; 
quit;
/* Manually check whether the contract's lenders, loan type, loan amount, and maturity in my sample are the same as those in DealScan */

proc expand data=thesis.gvkey_quarter out=thesis.gvkey_quarter_4 method=none;
by gvkey; id datadate;
convert datadate=datadate_lag1/transformout=(nomiss lag 1);
convert datadate=datadate_lag2/transformout=(nomiss lag 2);
convert datadate=datadate_lag3/transformout=(nomiss lag 3);
convert datadate=datadate_lag4/transformout=(nomiss lag 4);
convert datadate=datadate_lead1/transformout=(nomiss lead 1);
convert datadate=datadate_lead2/transformout=(nomiss lead 2);
convert datadate=datadate_lead3/transformout=(nomiss lead 3);
convert datadate=datadate_lead4/transformout=(nomiss lead 4);
run;
proc sql;
create table thesis.exhibit10_gaap as
 select a.*, b.datadate as facilitystart_datadate, b.datadate_lag1 as facilitystart_datadatelag1, b.fyearq as facilitystart_fyearq
 from thesis.exhibit10_gaap as a left join thesis.gvkey_quarter_4 as b
 on a.gvkey=b.gvkey and a.facilitystartdate>b.datadate_lag1 and a.facilitystartdate<=b.datadate;

/* Control variables collected from Compustat: Firm Size, sales growth & Rating */
proc sort data=thesis.model1_controlvariable out=thesis.model1_controlvariable nodupkey;
by gvkey datadate;
run;
proc expand data=thesis.model1_controlvariable out=thesis.model1_controlvariable method=none;
by gvkey; id datadate;
convert REVT=REVT_lag1/transformout=(nomiss lag 1);
run;
data thesis.model1_controlvariable;
set thesis.model1_controlvariable;
sale_growth=(REVT-REVT_lag1)/REVT_lag1;
if at=. then delete;
if at=0 then delete;
size=log(at);
roa=ib/at;
dbta=(dltt+dlc)/at;
if dvt>0 then div=1;
else div=0;
if ds>0 then subdbt=1;
else subdbt=0;
if roa<0 then neg=1;
else neg=0;
rating=-0.57*size-4.28*roa+2.19*dbta-1.03*div+0.35*subdbt+0.31*neg;

data thesis.lender_reputation;
set thesis.lender;
if LEADARRANGERCREDIT^="Yes" then delete;
run;
data thesis.facility_1990_2021;
set thesis.facility_1990_2021;
if COUNTRYOFSYNDICATION^="USA" then delete;
if CURRENCY^="United States Dollars" then delete;
run;
proc sql;
create table thesis.lender_reputation as
select a.*, b.FACILITYSTARTDATE, b.FACILITYAMT, b.PACKAGEID
from thesis.lender_reputation as a, thesis.facility_1990_2021 as b
where a.facilityid=b.facilityid;
quit;
data thesis.lender_reputation;
set thesis.lender_reputation;
year=year(FACILITYSTARTDATE);
comb=COMPANYID||year;

/* Control variables: Num_GAAP_Change */
/*From 1993 to 2008, the number of sfas pronouncement per year; From 2009 to 2017, the number of fasb updates*/
proc sql;
create table thesis.exhibit10_gaap_model1 as
select a.*, b.number_ac as lag_number_ac
from thesis.exhibit10_gaap_model1 as a left join thesis.accounting_change as b
on a.facilitystart_fyearq=b.year+1;

/* Control variables collected from SEC Analytics Suite by WRDS: Financial Complexity */
/* The number of words in the most recent 10-K */
proc sql;
create table thesis.exhibit10_gaap_model1 as
select a.*, b.WORDCOUNT
from thesis.exhibit10_gaap_model1 as a left join thesis.number_word as b
on a.gvkey=b.gvkey and a.facilitystart_fyearq=b.fyear+1;

/* Control variables collected from CRSP: Return Volatility */
proc expand data=thesis.monthly_return out=thesis.monthly_return_std method=none;
by permno; id date;
convert ret=ret_1/transformout=(nomiss lag 1);
convert ret=ret_2/transformout=(nomiss lag 2);
convert ret=ret_3/transformout=(nomiss lag 3);
convert ret=ret_4/transformout=(nomiss lag 4);
convert ret=ret_5/transformout=(nomiss lag 5);
convert ret=ret_6/transformout=(nomiss lag 6);
convert ret=ret_7/transformout=(nomiss lag 7);
convert ret=ret_8/transformout=(nomiss lag 8);
convert ret=ret_9/transformout=(nomiss lag 9);
convert ret=ret_10/transformout=(nomiss lag 10);

nvalues = N(ret,ret_1, ret_2, ret_3, ret_4, ret_5, ret_6, ret_7, ret_8, ret_9, ret_10, ret_11, ret_12, ret_13, ret_14, ret_15,
ret_16, ret_17, ret_18, ret_19, ret_20, ret_21, ret_22, ret_23, ret_24, ret_25, ret_26, ret_27, ret_28, ret_29, ret_30,
ret_31, ret_32, ret_33, ret_34, ret_35);
nmiss = nmiss(ret,ret_1, ret_2, ret_3, ret_4, ret_5, ret_6, ret_7, ret_8, ret_9, ret_10, ret_11, ret_12, ret_13, ret_14, ret_15,
ret_16, ret_17, ret_18, ret_19, ret_20, ret_21, ret_22, ret_23, ret_24, ret_25, ret_26, ret_27, ret_28, ret_29, ret_30,
ret_31, ret_32, ret_33, ret_34, ret_35);
run;
proc sql;
  create table  thesis.monthly_return_std as
  select a.*, b.gvkey, b.linkdt, b.linkenddt
  from  thesis.monthly_return_std as a, thesis.ccm as b
  where a.permno=b.lpermno and b.linkprim in ('P', 'C') and
  b.LINKTYPE in ('LU', 'LC') and a.date >= b.LINKDT and (a.date <= b.LINKENDDT or missing(b.LINKENDDT))
  order by permno, date;
quit;
data thesis.monthly_return_std;
set thesis.monthly_return_std;
if nvalues_new<30 then delete;

data thesis.model2_crsp;
set thesis.model2_crsp_20220124;
abnormalreturn=RET-VWRETD;
abnormalreturn1=abnormalreturn+1;
run;
proc sort data=thesis.model2_crsp nodupkey;
by permno date;
run;
proc expand data=thesis.model2_crsp out=thesis.model2_crsp method=none;
by permno; id date;
convert abnormalreturn1=abnormalreturn1_3/transformout=(nomiss movprod 3 trimleft 2);
run;
data thesis.model2_crsp;
set thesis.model2_crsp;
quarter_return=abnormalreturn1_3-1;
run;
proc sql;
  create table thesis.model2_crsp as
  select a.*, b.gvkey, b.linkdt, b.linkenddt
  from thesis.model2_crsp as a, thesis.ccm as b
  where a.permno=b.lpermno and b.linkprim in ('P', 'C') and
  b.LINKTYPE in ('LU', 'LC') and a.date >= b.LINKDT and (a.date <= b.LINKENDDT or missing(b.LINKENDDT))
  order by permno, date;

/* Merge positive return sample with the violations occurring during the current quarter and the following three quarters*/
/* Covenant violation data is handly collected. Table 1, panel B in the main text summarizes the data collection procedures. */
/* To better capture actual violations of financial covenants in loan contracts, I exclude 
(i) covenant amendments and waivers obtained prior to compliance testing dates such as future covenant holidays; 
(ii) financial covenant violations in foreign subsidiaries 
or indirect subsidiaries whose loan contracts are not reported under the borrower�fs CIK; 
(iii) financial covenant violations in non-loan contracts such as lease agreements; 
and (iv) violations of debt payment obligations and other covenants relating to reporting, audit opinion, going 
concern, and financial restatements.  
I also exclude violations of capital expenditure and M&A covenants if they are disclosed.*/
proc sql;
create table thesis.model2_crsp_positive as
select a.*, b.viol
from thesis.model2_crsp_positive as a left join thesis.covenantviolation_9517 as b
on b.gvkey=a.gvkey and b.datadate_quarter>a.datadate_lag1 and b.datadate_quarter<a.DATADATE_lead3+7;
quit;

/* Calaulate the probability of performance covenant violations using the SAS code shared by Demerjian and Owens (2016)*/
proc sql;
create table thesis.model2_crsp_positive as 
select a.*, b.pviol_pcov
from thesis.model2_crsp_positive as a left join thesis.pviol_2022 as b
on a.packageid=b.packageid;

proc sort data=thesis.controlvariable_compustat out=thesis.controlvariable_compustat nodupkey;
by gvkey datadate;
run;
proc expand data=thesis.controlvariable_compustat out=thesis.controlvariable_compustat method=none;
by gvkey; id datadate;
convert OANCFY=OANCFY_lag1/transformout=(nomiss lag 1);
convert IBQ=IBQ_movsum4/transformout=(nomiss movsum 4 trimleft 3);
convert REVTQ=REVTQ_sum4/transformout=(nomiss movsum 4 trimleft 3);
convert REVTQ=REVTQ_sum8/transformout=(nomiss movsum 8 trimleft 7);
run;
data thesis.controlvariable_compustat;
set thesis.controlvariable_compustat;
if FQTR=1 then oancf_q=OANCFY;
else if FQTR>1 then oancf_q=OANCFY-OANCFY_lag1;
run;
proc expand data=thesis.controlvariable_compustat out=thesis.controlvariable_compustat method=none;
by gvkey; id datadate;
convert oancf_q=oancf_q_movsum4/transformout=(nomiss movsum 4 trimleft 3);
convert oancf_q_movsum4=oancf_movsum4_std4/transformout=(nomiss movstd 4 trimleft 3);
run;
data thesis.controlvariable_compustat;
set thesis.controlvariable_compustat;
if atq=0 then delete;
if atq=. then delete;
if dlcq=. then dlcq=0;
leverage=(dlttq+dlcq)/atq;
size=log(1+atq);
roa_annual=IBQ_movsum4/atq;
sale_growth=(REVTQ_sum4-(REVTQ_sum8-REVTQ_sum4))/(REVTQ_sum8-REVTQ_sum4);
run;

data thesis.model2_fisd;
set thesis.model2_fisd_1950_2020;
if rating_type not in ('SPR', 'FR', 'MR') then delete;
if rating_date>'01Jan2018'd then delete;
if rating_date<'01Jan1996'd then delete;
run;
proc sql;
create table thesis.model2_fisd as
select a.*, b.permno
from thesis.model2_fisd as a, thesis.wrdsapps_link_crsp_bond as b
where a.complete_cusip=b.cusip and a.rating_date>=b.LINK_STARTDT and a.rating_date<=b.LINK_ENDDT;

data thesis.model3_crsp;
set thesis.model3_crsp_monthly;
return=RET-VWRETD;
if date>'01Jan2018'd then delete;
if date<'01Jan1996'd then delete;
run;
proc sql;
  create table thesis.model3_crsp as
  select a.*, b.gvkey, b.linkdt, b.linkenddt
  from thesis.model3_crsp as a, thesis.ccm as b
  where a.permno=b.lpermno and b.linkprim in ('P', 'C') and
  b.LINKTYPE in ('LU', 'LC') and a.date >= b.LINKDT and (a.date <= b.LINKENDDT or missing(b.LINKENDDT))
  order by permno, date;
quit;
proc sort data=thesis.model3_crsp nodupkey;
by permno date;
run;
%winsor(dsetin=thesis.model3_crsp, dsetout=thesis.model3_crsp, byvar=none,  
vars=return, type=winsor, pctl=1 99);

create table thesis.model2_crsp_positive as 
select a.*, b.dvt as dvt_lag1
from thesis.model2_crsp_positive as a left join THESIS.dividend as b
on a.gvkey=b.gvkey and a.FYEARQ=b.fyear+1;
quit;
data thesis.model2_crsp_positive;
set thesis.model2_crsp_positive;
if dvt_lag1!=. & dvt_lag1!=0 then dividend=1;
else if dvt_lag1=0 then dividend=0;
run;
